ExercisePledge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ExercisePledge {
    // --- Roles ---
    address payable public owner;        // the student / deployer
    address public punchingBall;         // who is allowed to report a check-in

    // --- Timing config ---
    uint256 public totalEnd;             // when the whole program ends
    uint256 public nextDeadline;         // next check-in is due by this time
    uint256 public frequency;            // length of each check-in window (seconds)

    // --- Events for the console / UI ---
    event Deployed(address indexed owner, address indexed punchingBall, uint256 stake);
    event CheckedIn(address indexed by, uint256 at, uint256 nextDeadline);
    event Burned(uint256 amount, string reason);
    event Withdrawn(address indexed to, uint256 amount);

    constructor(
        address _punchingBall,       // who will call checkIn()
        uint256 totalDays,           // e.g., 30
        uint256 frequencyDays        // e.g., 2
    ) payable {
        require(_punchingBall != address(0), "punchingBall required");
        require(totalDays > 0 && frequencyDays > 0, "days > 0");
        require(totalDays >= frequencyDays, "total >= frequency");

        owner = payable(msg.sender);
        punchingBall = _punchingBall;

        frequency = frequencyDays * 1 days;
        totalEnd  = block.timestamp + (totalDays * 1 days);
        nextDeadline = block.timestamp + frequency;

        emit Deployed(owner, punchingBall, msg.value);
    }

    /// Anyone can top up the stake (optional, keeps it simple for class).
    receive() external payable {}

    /// Called by the punchingBall to prove you exercised.
    /// On time (<=) → slide the deadline forward by one frequency (capped at totalEnd).
    /// Late (>)     → burn everything immediately.
    function checkIn() external {
        require(msg.sender == punchingBall, "only punchingBall");
        require(block.timestamp < totalEnd, "program ended");

        if (block.timestamp <= nextDeadline) {
            // Slide one window forward, but never past the final end.
            uint256 candidate = nextDeadline + frequency;
            nextDeadline = candidate > totalEnd ? totalEnd : candidate;
            emit CheckedIn(msg.sender, block.timestamp, nextDeadline);
        } else {
            _burnAll("late check-in");
        }
    }

    /// After the total window ends: if you never missed, you get your stake back;
    /// otherwise, the stake has been (or will be) burned.
    function withdraw() external {
        require(msg.sender == owner, "only owner");
        require(block.timestamp >= totalEnd, "too early");

        if (nextDeadline >= totalEnd) {
            uint256 amount = address(this).balance;
            (bool ok, ) = owner.call{value: amount}("");
            require(ok, "send failed");
            emit Withdrawn(owner, amount);
        } else {
            _burnAll("not enough practice");
        }
    }

    // --- helpers ---

    function _burnAll(string memory reason) internal {
        uint256 amount = address(this).balance;
        if (amount > 0) {
            (bool ok, ) = payable(address(0)).call{value: amount}(""); // send to the zero address
            require(ok, "burn failed");
            emit Burned(amount, reason);
        }
        // Optional: lock further actions; we keep it simple for class.
    }

    // Convenience views for the UI / questions
    function secondsToNextDeadline() external view returns (uint256) {
        return block.timestamp >= nextDeadline ? 0 : (nextDeadline - block.timestamp);
    }

    function secondsToEnd() external view returns (uint256) {
        return block.timestamp >= totalEnd ? 0 : (totalEnd - block.timestamp);
    }
}

